@dataclass(frozen=True)
class SpecNode:
    path: Path
    data: dict[str, Any]

    @property
    def id(self) -> str:
        return str(self.data.get("id", "")).strip()

    @property
    def title(self) -> str:
        return str(self.data.get("title", "")).strip()

    @property
    def status(self) -> str:
        return str(self.data.get("status", "stub")).strip()

    @property
    def gate_state(self) -> str:
        return str(self.data.get("gate_state", "none")).strip() or "none"

    @property
    def allowed_paths(self) -> list[str]:
        value = self.data.get("allowed_paths", [])
        return list(value) if isinstance(value, list) else []

def _has_reviewable_gap(gaps: list[Any], term: str | None = None) -> bool:
    for raw_gap in gaps:
        gap = _dict(raw_gap)
        if gap.get("canonical_mutations_allowed") is not False:
            continue
        if _text(gap.get("status")) not in REVIEWABLE_GAP_STATUSES:
            continue
        if not _text(gap.get("proposed_term")):
            continue
        if term is None or _text(gap.get("proposed_term")).lower() == term.lower():
            return True
    return False

def _safe_path(value: Any) -> str:
    if not isinstance(value, str) or not value:
        raise IncrementalStageError("manifest file path must be a non-empty string")
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or value != path.as_posix():
        raise IncrementalStageError(f"manifest file path is unsafe: {value!r}")
    return value

def _manifest_files(payload: Any) -> dict[str, dict[str, Any]]:
    if not isinstance(payload, dict) or not isinstance(payload.get("files"), list):
        raise IncrementalStageError("artifact manifest must contain files[]")
    files: dict[str, dict[str, Any]] = {}
    for row in payload["files"]:
        if not isinstance(row, dict):
            raise IncrementalStageError("artifact manifest files[] entries must be objects")
        path = _safe_path(row.get("path"))
        digest = row.get("sha256")
        if not isinstance(digest, str) or len(digest) != 64:
            raise IncrementalStageError(f"manifest sha256 is invalid for {path}")
        if path in files:
            raise IncrementalStageError(f"artifact manifest contains duplicate path: {path}")
        files[path] = row
    return files
